  str_n0_h10_name = "EX4 - Húbris",
  str_n0_h11_name = "EX5 - Subjugação",
  str_n0_h12_name = "EX6 - Recolher",
  str_n0_h1_name_desc = "Às vezes, apenas o ritmo das ondas é suficiente para mudar a situação no campo de batalha.",
  str_n0_h2_name_desc = "Nas batalhas navais, os recifes são como armadilhas que podem ser usadas por qualquer um dos lados para reivindicar a vitória. Durante as batalhas terrestres, engenhocas mecânicas servem ao mesmo propósito.",
  str_n0_h3_name_desc = "Ouvir aquela voz, ver aquela figura... Você sabe que não está sozinho.",
  str_n0_h4_name_desc = "Guardar a glória é guardar a esperança. Não importa o que o futuro reserva, esta é uma verdade inegável.",
  str_n0_h5_name_desc = "Embora o inimigo enfrente repercussões por suas ações, isso também significa que a batalha está prestes a se tornar muito mais difícil.",
  str_n0_h6_name_desc = "Não se deixe intimidar pelo número de inimigos. A melhor forma de eliminar o medo é enfrentá-lo de frente.",
  str_n0_h7_name_desc = "Quando mais e mais inimigos aparecem, formando um mar de inimigos, talvez o caminho para a vitória esteja em encolher sua linha defensiva e concentrar seu poder em uma resistência unida.",
  str_n0_h8_name_desc = "É quase como se seu inimigo tivesse o poder de vencer a qualquer momento, mas preferia brincar com você do que terminar a batalha cedo demais...",
  str_n0_h9_name_desc = "Sempre que um inimigo estiver gravemente ferido, você pode ter certeza de que seu contra-ataque será ainda mais frenético do que antes.",
  str_n0_h10_name_desc = "Quando o inimigo está em perigo, eles chamam seus aliados para reforço. Eliminá-los rapidamente é a única maneira de reivindicar a vitória.",
  str_n0_h11_name_desc = "Esteja preparado para lidar com várias situações no campo de batalha e reprimir o inimigo até o fim. Infelizmente, o inimigo fará exatamente o mesmo.",
  str_n0_h12_name_desc = "Quando a terra está despedaçada e não há para onde correr, como podemos encontrar uma chance de emergir triunfante?",
  str_n0_1_name = "ST1 - Içando a Vela",
  str_n0_2_name = "N1 - A Família Lin",
  str_n0_3_name = "N2 - Tempestade",
  str_n0_4_name = "N3 - Sinais",
  str_n0_5_name = "N4 - Rattled",
  str_n0_6_name = "N5 - Cauda do Rato",
  str_n0_7_name = "N6 - Cabeça de Macaco",
  str_n0_8_name = "ST2 - Orelhas de Coelho",
  str_n0_9_name = "N7 - Atrito",
  str_n0_10_name = "N8 - Fome",
  str_n0_11_name = "N9 - Navio Perdido",
  str_n0_12_name = "N10 - A Bordo",
  str_n0_13_name = "N11 - A Bússola",
  str_n0_14_name = "N12 - Última Resistência",
  str_n0_15_name = "ST3 - Desembarque",
  str_n0_1_name_desc = "/",
  str_n0_2_name_desc = "À medida que Zhong Xu, um velho amigo da família Lin, conta mais, você gradualmente junta uma impressão mais concreta da família Lin em sua mente.",
  str_n0_3_name_desc = "Uma tempestade se aproxima e você decide ir para o convés para ajudar Yuebai e Liqing. Em meio ao caos, você sente criaturas incomuns no mar...",
  str_n0_4_name_desc = "O Shadowind está muito danificado e mal consegue continuar navegando. Nesta situação terrível, parece que você só pode rezar para que os céus sejam benevolentes...",
  str_n0_5_name_desc = "Procurar a Bússola perdida nas profundezas e caçar as peças necessárias nos destroços é como tentar pescar uma agulha no oceano... Será que você consegue mesmo?",
  str_n0_6_name_desc = "Os animais às vezes têm instintos mais aguçados do que os aurorianos e podem encontrar coisas que não podem ser facilmente vistas a olho nu.",
  str_n0_7_name_desc = "Às vezes, os animais sabem mais sobre cooperação do que os aurorianos e podem transmitir informações com precisão a seus amigos de confiança.",
  str_n0_8_name_desc = "/",
  str_n0_9_name_desc = "Você deve persistir, quer consiga ou não obter resultados.",
  str_n0_10_name_desc = "O medo da fome é um instinto primitivo. Todos devem fazer o que podem para aliviar seu mal-estar.",
  str_n0_11_name_desc = "Você deve arriscar para ver se realmente há esperança em algum lugar no vasto oceano.",
  str_n0_12_name_desc = "Este não é o Shadowind que você conhece. O que é esse lugar, exatamente?",
  str_n0_13_name_desc = "A Bússola está logo ali. Você quase pode tocá-lo.",
  str_n0_14_name_desc = "Os animais às vezes guardam rancores mais profundos do que os aurorianos. Tudo o que eles sofrem será devolvido dez vezes.",
  str_n0_15_name_desc = "/",
  str_n0_1_name_desc_long = "Twin Pavilions Bay está vivo com a atmosfera do Festival da Primavera, um festival tradicional de Longzhou. Você e os outros passageiros do Shadowind estão aqui há algum tempo e finalmente estão se preparando para sua partida. No entanto, no momento em que o Shadowind está prestes a zarpar, Piu-Piu o encontra novamente e lhe entrega uma carta para ser enviada através do oceano. A pedido de Tweety, você decide ir para o continente de Longzhou em seu nome, embarcando no Shadowind.",
  str_n0_2_name_desc_long = "Zhong Xu e Liqing, seus novos conhecidos de Twin Pavilions Bay, parecem ter alguma conexão com o navio em que você está. Na mesa de jantar, Zhong Xu conta sobre sua experiência à deriva para Astra meio ano atrás, quando ele e Liqing se depararam com o infortúnio a bordo do Shadowind. Como resultado desse incidente, não apenas o Lin Guildmaster ficou gravemente ferido, o orgulhoso dispositivo de navegação da família Lin, The Compass, afundou no mar com o velho navio.",
  str_n0_3_name_desc_long = "Uma turbulência repentina desperta cada hóspede um a um enquanto descansam na cabine. Uma tempestade caiu. Vento, trovão e chuva clamam ao seu redor. Em vez de seguir a equipe de resgate, você vai para o convés. Yuebai está liderando a tripulação para estabilizar o navio enquanto Liqing se encolhe para o lado com medo. Quando você usa sua habilidade psíquica para encontrar seus companheiros, um cardume de peixes-serpentes começa a atacar freneticamente o Shadowind.",
  str_n0_4_name_desc_long = "Depois de uma noite passada em uma luta feroz entre a vida e a morte, o Shadowind fica cheio de buracos e todas as seções importantes do casco são perdidas. Felizmente, você e seus companheiros ainda estão vivos, mas a situação é terrível. Os suprimentos acabarão em breve - você deve encontrar uma maneira de navegar novamente. Li Tianxian, conhecido por todos como um charlatão, fornece três adivinhações para o Shadowind, que dá inspiração a Yuebai.",
  str_n0_5_name_desc_long = "Com a experiência de Zhong Xu a bordo de um navio que está afundando, você decide apostar tudo no relançamento do Shadowind e começa a procurar as peças de que precisa. As velas foram danificadas, por isso só pode ser remada manualmente com remos. Se ele navegar lentamente em tempo ensolarado, você ainda pode ter uma chance de mudar seu destino. As pessoas a bordo estão abaladas, mas Yuebai é muito firme sobre o que deve ser feito. Se ela mostrasse algum medo, ninguém acreditaria que existisse um único traço de esperança.",
  str_n0_6_name_desc_long = "Todos partem um após o outro e decidem procurar o cata-vento perdido - o rabo do rato - a bordo do enorme Shadowind. Dantang também deseja fazer algo para ajudar a salvar o Shadowind, mas ela não sabe nada sobre o rabo do rato. Tianxian aparece com seus dois pássaros falantes. Eles circulam no céu acima e encontram a cauda do rato com facilidade.",
  str_n0_7_name_desc_long = "Liqing insiste em levar o bote salva-vidas para o mar sozinho para salvar uma polia apelidada de \"cabeça de macaco\", mas ele hesita devido ao seu medo inato de água. Preocupado, você pega um bote salva-vidas e flutua no mar calmo com ele. Liqing sabe claramente para onde vocês dois estão indo e consegue pescar a cabeça do macaco de um naufrágio. Ele diz que foi tudo graças ao seu \"amigo do mar\".",
  str_n0_8_name_desc_long = "Para consertar o Shadowind, você começa a tentar resgatar peças especiais de navios naufragados - as orelhas de coelho. Eles são usados para cobrir os vazamentos no fundo do navio, aliviando com sucesso a pressão no Shadowind. Até agora, o trabalho de reparo foi em grande parte concluído. Os marinheiros se reúnem para comemorar e todos começam a acreditar que o resto da viagem será um sucesso.",
  str_n0_9_name_desc_long = "Com o passar do tempo, o otimismo dos marinheiros vai diminuindo. Mais e mais problemas práticos começam a surgir. Com materiais insuficientes, os tripulantes adoecem e, agora, outra tempestade bloqueia o caminho.",
  str_n0_10_name_desc_long = "Os suprimentos de comida estão acabando e os marinheiros não têm escolha a não ser passar mais tempo pescando. Inesperadamente, um peixe-serpente é pego por acidente, um incidente que quase vira o navio. Liqing apressadamente diz à tripulação para soltar o peixe-serpente, evitando um grande desastre. No entanto, Zhong Xu vê outra coisa. Ele encontra o capitão sozinho e anuncia que The Compass está logo à frente.",
  str_n0_11_name_desc_long = "Você vê os destroços do velho Shadowind do convés. Yuebai imediatamente pula na água, e você e Liqing seguem logo atrás de barco. Mas então uma névoa repentina desce sobre o mar e nada pode ser visto em meio ao vasto manto branco. Yuebai se junta a você e conta que encontrou um navio perdido no fundo do oceano. À medida que você deriva, um enorme navio aparece à sua frente.",
  str_n0_12_name_desc_long = "Você embarca no enorme navio no meio do nevoeiro, apenas para não encontrar ninguém a bordo. Não parece ser o Shadowind... Mas somente Liqing o reconhece. É o velho Shadowind. Animado, ele leva você para procurar a Bússola. Enquanto isso, no Shadowind atual, Zhong Xu conta a todos sobre os últimos momentos do antigo Shadowind. Enquanto ele conta sua história, um barulho repentino enche o ar - eles têm companhia.",
  str_n0_13_name_desc_long = "Enquanto você procura pela Bússola na cabana do antigo Shadowind, alguém de repente o tranca dentro da sala. Liqing exclama que o culpado é na verdade The Compass - ele era originalmente um peixe-serpente, mas agora se transformou em um demônio com poder fenomenal. Se você não pegá-lo logo, todos os seus esforços serão em vão.",
  str_n0_14_name_desc_long = "Zhong Xu leva os outros a embarcar no velho navio e encontra The Compass - agora um demônio vivo. Ele está cheio de ressentimento em relação a todos os aurorianos e ao navio que o aprisionou. Ele tenta enviar todos vocês para o fundo do oceano. Depois de uma batalha feroz, você o derrota, mas seu ódio faz todos repensarem suas decisões. Yuebai o solta no mar para corrigir os erros do passado. O Shadowind inicia a última etapa de sua viagem e você parte para Longzhou. De repente, o peixe-serpente emerge do mar e carrega o gigantesco navio nas costas.",
  str_n0_15_name_desc_long = "O Shadowind finalmente atraca com sucesso e sua desventura finalmente termina. Você passa o Festival da Primavera com a família Lin. A carta que você trouxe é peculiar, mas sua missão está completa. Alguns dias depois, Yuebai o convida para ver o Shadowind para testemunhar seu retorno à glória. Você assina seu nome no navio - o Shadowind o levará de um lado para o outro entre Longzhou e Astra, gravando para sempre seu nome no mar.",
  str_n0_food_name_1 = "Peixe no vapor",
  str_n0_food_name_2 = "bolas de gergelim",
  str_n0_food_name_3 = "Carne de porco assada",
  str_n0_food_name_4 = "Camarões",
  str_n0_food_name_5 = "Rolinho primavera",
  str_n0_food_name_6 = "Almôndegas Sixi",
  str_n0_food_name_7 = "Arroz misturado",
  str_n0_food_name_8 = "pizza de tomate",
  str_n0_food_name_9 = "ovo cozido no vapor",
  str_n0_food_name_10 = "pepitas",
  str_n0_food_name_11 = "panela quente",
  str_n0_food_name_12 = "bife grelhado",
  str_n0_food_name_13 = "Udon",
  str_n0_food_name_14 = "Arroz frito",
  str_n0_food_desc_1 = "Peixe marinado em gengibre e vinho de cozinha, depois cozido no vapor em uma panela. O molho de soja é adicionado sobre ele para obter a quantidade certa de sabor umami.",
  str_n0_food_desc_2 = "Uma sobremesa simples e deliciosa feita de arroz glutinoso e recheada com gergelim preto. Adequado para os jovens e velhos.",
  str_n0_food_desc_3 = "Carne de porco em cubos cozida em molho de soja ou açúcar até dourar perfeitamente. Gorduroso, mas não enjoativo.",
  str_n0_food_desc_4 = "Bolinhos recheados com camarão, fervidos em água e depois colocados em uma panela a vapor. Springy e sumptuoso, cada mordida é preenchida com sabor.",
  str_n0_food_desc_5 = "Rolinhos primavera fritos até ficarem dourados e crocantes, feitos com carne desfiada, repolho, coalhada de feijão e muito mais. Um deleite crocante com sabores complexos.",
  str_n0_food_desc_6 = "Almôndegas de porco e frutos do mar fritas primeiro, depois cozidas. O molho tem uma cor viva, aroma e sabor.",
  str_n0_food_desc_7 = "Arroz e ingredientes variados cozidos em uma panela até formar uma camada de arroz crocante no fundo. O cheiro é rico e irresistível.",
  str_n0_food_desc_8 = "Uma base de farinha coberta com tomates, cogumelos e mais assados com perfeição. Adequado para compartilhar.",
  str_n0_food_desc_9 = "Ovos batidos e cozidos no vapor em uma panela, depois temperados com molho de soja com cebolinha para enfeitar. Embora simples, é um prato muito popular em Longzhou.",
  str_n0_food_desc_10 = "Frango em cubos coberto com massa e frito até dourar e ficar crocante por fora e macio por dentro.",
  str_n0_food_desc_11 = "Carne grelhada na panela de ferro, temperada com molho agridoce de soja. Complementado por cogumelos, cenouras, tofu e outros acompanhamentos.",
  str_n0_food_desc_12 = "Bife de corte central, frito em frigideira de ferro com manteiga até dourar os dois lados, servido com molho de pimenta-do-reino.",
  str_n0_food_desc_13 = "Macarrão grosso feito de farinha, sal e água. Geralmente cozido em um caldo.",
  str_n0_food_desc_14 = "Arroz coberto com ovos, mexa até dourar. Pode incluir cogumelos, ervilhas, cenouras, camarões e muito mais para um sabor rico.",
  str_n0_food_tishi_1 = "o <color=#b74b25>Farinha</color> e <color=#b74b25>Tempero</color> proporção da porção deve ser 2:1.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_2 = "O número de porções de <color=#b74b25>Vegetal</color> e <color=#b74b25>Tempero</color> deve ser igual.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_3 = "O número de porções de <color=#b74b25>Vegetal</color> e <color=#b74b25>Tempero</color> deve ser igual.\nO número de porções de <color=#b74b25>Frutos do mar</color> deve ser menor que a soma dos outros dois ingredientes.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_4 = "O número de <color=#b74b25>Eu no</color> as porções devem ser o dobro do número de <color=#b74b25>Tempero</color> porções.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_5 = "O número de <color=#b74b25>Farinha</color> as porções devem ser maiores que a soma dos outros dois ingredientes.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_6 = "O número de porções de <color=#b74b25>Farinha</color> deve ser maior que a soma dos outros dois ingredientes.\nO número de porções de <color=#b74b25>Frutos do mar</color> e <color=#b74b25>Vegetal</color> deve ser igual.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_7 = "O número de porções de <color=#b74b25>Vegetal</color> e <color=#b74b25>Eu no</color> deve ser igual.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_8 = "O número de porções de <color=#b74b25>Vegetal</color> e <color=#b74b25>Carne</color> deve ser igual.\nO número de porções de <color=#b74b25>Farinha</color> deve ser o dobro do número de porções de <color=#b74b25>Vegetal</color>.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_9 = "O número de <color=#b74b25>Eu no</color> as porções devem ser maiores que a soma dos outros três ingredientes.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_10 = "O número de porções de <color=#b74b25>Carne</color> deve ser maior que a soma dos outros três ingredientes.\nO número de porções de <color=#b74b25>Ovo</color> e <color=#b74b25>Tempero</color> deve ser igual.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_11 = "O número de <color=#b74b25>Arroz</color> as porções devem ser iguais à soma dos outros três ingredientes, e a menor porção deve ser a <color=#b74b25>Ovos</color>.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_12 = "O número de porções de <color=#b74b25>Arroz</color> deve ser igual à soma dos outros três ingredientes, e a menor porção deve ser a de <color=#b74b25>Ovos</color>.\nO número de porções de <color=#b74b25>Vegetal</color> e <color=#b74b25>Carne</color> deve ser igual.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_13 = "Deve haver mais um <color=#b74b25>Vegetal</color> porção do que há <color=#b74b25>Eu no</color> porções.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
  str_n0_food_tishi_14 = "Deve haver mais uma porção de <color=#b74b25>Vegetal</color> do que porções de <color=#b74b25>Carne</color>.\nO número de porções de <color=#b74b25>Farinha</color> deve ser menor que a soma dos outros dois ingredientes.\n<color=#b74b25>Deve ser adicionada pelo menos 1 porção de cada ingrediente.</color>",
